//! What both SDKs agree on: batching, retries, limits and the scrubbing rules. Each value
//! is written once, here. With the `ts` feature the tests write them to
//! `sdk/src/generated/policy.ts`, which `@bigbertha/sdk` imports, so the two SDKs can't
//! drift apart (CI fails when the generated file is out of date).

// Without the client only the generated file reads these.
#![cfg_attr(not(feature = "client"), allow(dead_code))]

macro_rules! policy {
    ($( $(#[doc = $doc:literal])+ $name:ident: $ty:ty = $value:expr; )+) => {
        $( $(#[doc = $doc])+ pub(crate) const $name: $ty = $value; )+

        /// The TypeScript module `@bigbertha/sdk` imports.
        #[cfg(all(test, feature = "ts"))]
        pub(crate) fn typescript() -> String {
            let mut out = String::from(
                "// Generated from server/crates/bigbertha/src/policy.rs by its tests. Do not edit this file manually.\n",
            );
            $(
                let doc: Vec<&str> = [$($doc),+].iter().map(|l| l.trim()).collect();
                out.push_str(&format!("\n/** {} */\nexport const {} = {}\n", doc.join(" "), stringify!($name), Ts::ts(&$name)));
            )+
            out
        }
    };
}

policy! {
    /// Events or log lines in one request.
    BATCH: usize = 100;
    /// How long a capture waits for others to join its batch, in milliseconds.
    DEBOUNCE_MS: u64 = 1000;
    /// Events a client sends in a minute; the rest are dropped.
    PER_MINUTE: u32 = 100;
    /// Breadcrumbs kept for the next event.
    MAX_BREADCRUMBS: usize = 100;
    /// Log lines waiting to be sent; past it the oldest are dropped, and counted.
    MAX_LOGS: usize = 1000;
    /// Causes followed down from an error.
    MAX_CAUSES: usize = 5;
    /// Fields taken from an error or a tracing event.
    MAX_FIELDS: usize = 20;
    /// Characters kept of each field.
    FIELD_CHARS: usize = 500;
    /// Bodies from this many bytes are gzipped (bertha sniffs the gzip header).
    GZIP_FROM: usize = 1024;
    /// How long one request to bertha may take, in milliseconds.
    SEND_TIMEOUT_MS: u64 = 10_000;
    /// Retries straight after a failed send, waiting RETRY_BASE_MS × 2^attempt between them.
    RETRIES: u32 = 3;
    /// The first wait between retries, in milliseconds.
    RETRY_BASE_MS: u64 = 500;
    /// How long a batch is kept while bertha can't be reached, in milliseconds, so a network blip loses nothing.
    OUTAGE_MS: u64 = 5 * 60 * 1000;
    /// The wait after a round of retries before the next, in milliseconds.
    OFFLINE_PAUSE_MS: u64 = 30_000;
    /// The wait after a 429 or 503 that didn't say how long, in seconds.
    DEFAULT_PAUSE_SECONDS: u64 = 60;
    /// Email addresses in text become `[email]`.
    EMAIL: &str = r"[A-Za-z0-9_.+-]+@[A-Za-z0-9_-]+\.[A-Za-z0-9_.-]+";
    /// Credentials after Bearer or Basic become `[redacted]`. Case-insensitive.
    BEARER: &str = r"\b(Bearer|Basic)\s+[A-Za-z0-9_.~+/=-]+";
    /// Query values whose names look secret become `[redacted]`. Case-insensitive.
    SECRET_PARAM: &str = r"([?&](?:[^=&#]*(?:token|key|secret|password|passwd|auth|session|code|sig)[^=&#]*)=)[^&#\s]*";
    /// Fields, headers and tags whose names match are dropped. Case-insensitive.
    SENSITIVE_KEY: &str = r"password|passwd|secret|token|authorization|cookie|api_?key|credential|session";
}

#[cfg(all(test, feature = "ts"))]
trait Ts {
    fn ts(&self) -> String;
}

#[cfg(all(test, feature = "ts"))]
macro_rules! ts_number {
    ($($t:ty),+) => { $(impl Ts for $t { fn ts(&self) -> String { self.to_string() } })+ };
}
#[cfg(all(test, feature = "ts"))]
ts_number!(u32, u64, usize);

#[cfg(all(test, feature = "ts"))]
impl Ts for &str {
    fn ts(&self) -> String {
        serde_json::to_string(self).expect("a string serializes")
    }
}

#[cfg(all(test, feature = "ts"))]
mod tests {
    use std::path::PathBuf;

    /// Writes `sdk/src/generated/policy.ts` next to ts-rs's `ingest.ts`.
    #[test]
    fn export_policy() {
        let root = std::env::var_os("TS_RS_EXPORT_DIR")
            .map_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../.."), PathBuf::from);
        let path = root.join("sdk/src/generated/policy.ts");
        let fresh = super::typescript();
        if std::fs::read_to_string(&path).ok().as_deref() != Some(fresh.as_str()) {
            std::fs::write(&path, fresh).expect("writes sdk/src/generated/policy.ts");
        }
    }
}
